/** The shadow ramp's width: KERB_SHADOW_M, or the road look option's (round 2: 0.45 m did not read at 1:1 on the phone). */
let kerbShadowWidth = KERB_SHADOW_M;

/**
 * Earcut triangles draped where the relief needs it: a triangle is split at its longest edge while that edge is
 * longer than `maxEdge`, or longer than `minEdge` with the surface at any edge's midpoint or the centroid more than
 * `tol` off the triangle's plane (`sagOnly`: only a surface rising over the plane counts, the land showing through;
 * a plane floating over a hollow is left). parks.ts drapeBisect splits by length alone (8 m), which on the survey's
 * slivers cost 3.4× the earcut triangles of a cell (203k against 60k on -2_-1); streets are graded flat, so most
 * triangles pass the test unsplit, and the ramps, humps and quay edges get the splits. Testing the longest edge alone
 * left the Kinkerstraat asphalt 2.3 cm under the land at a quay mouth. A triangle under `minArea` m² splits by
 * `maxEdge` alone. Winding CCW from above, as drapeBisect.
 */
export function drapeAdaptive(m: MeshArrays, coords: ArrayLike<number>, tris: ArrayLike<number>, height: HeightFn, lift: number, maxEdge: number, tol: number, minEdge: number, floatTol = tol, minArea = 0, gateEdge = Infinity): void {
  const max2 = maxEdge * maxEdge, min2 = minEdge * minEdge, area2 = 2 * minArea, gate2 = gateEdge * gateEdge;
  // Each corner carries its height and its emitted vertex (-1: not yet): the earcut corners are drawn once and shared
  // by every triangle on them, and every height is asked once per corner (the tested midpoint becomes the split's).
  const nv = coords.length >> 1, zs = new Float64Array(nv), ids = new Int32Array(nv).fill(-1);
  for (let v = 0; v < nv; v++) zs[v] = height(coords[v * 2], coords[v * 2 + 1]);
  const stack: number[] = [];
  const bad = (d: number) => d > tol || -d > floatTol;
  for (let t = 0; t < tris.length; t += 3) {
    const a = tris[t], b0 = tris[t + 1], c0 = tris[t + 2];
    const cross = (coords[b0 * 2] - coords[a * 2]) * (coords[c0 * 2 + 1] - coords[a * 2 + 1]) - (coords[b0 * 2 + 1] - coords[a * 2 + 1]) * (coords[c0 * 2] - coords[a * 2]);
    // earcut's zero-area triangles on a ring's repeated or collinear vertices: nothing to draw (a sliver of one surface
    // lying on its neighbour's edge, under the pavement, in the junction-overlap probe).
    if (Math.abs(cross) < 1e-6) continue;
    const ccw = cross > 0;
    const b = ccw ? b0 : c0, c = ccw ? c0 : b0;
    // Corner records (x, y, z, earcut index or -1) × 3.
    stack.push(coords[a * 2], coords[a * 2 + 1], zs[a], a, coords[b * 2], coords[b * 2 + 1], zs[b], b, coords[c * 2], coords[c * 2 + 1], zs[c], c);
    while (stack.length) {
      const k3 = stack.pop()!, z3 = stack.pop()!, y3 = stack.pop()!, x3 = stack.pop()!, k2 = stack.pop()!, z2 = stack.pop()!, y2 = stack.pop()!, x2 = stack.pop()!, k1 = stack.pop()!, z1 = stack.pop()!, y1 = stack.pop()!, x1 = stack.pop()!;
      const e1 = (x2 - x1) ** 2 + (y2 - y1) ** 2, e2 = (x3 - x2) ** 2 + (y3 - y2) ** 2, e3 = (x1 - x3) ** 2 + (y1 - y3) ** 2;
      const longest = Math.max(e1, e2, e3), edge = longest === e1 ? 1 : longest === e2 ? 2 : 3;
      // The longest edge's midpoint first: its height is the split vertex's if the triangle splits.
      const mx = edge === 1 ? (x1 + x2) / 2 : edge === 2 ? (x2 + x3) / 2 : (x3 + x1) / 2, my = edge === 1 ? (y1 + y2) / 2 : edge === 2 ? (y2 + y3) / 2 : (y3 + y1) / 2;
      let mz = NaN, split = longest > max2;
      if (!split && longest > min2 && (!area2 || longest > gate2 || Math.abs((x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)) > area2)) {
        mz = height(mx, my);
        split = bad(mz - (edge === 1 ? (z1 + z2) : edge === 2 ? (z2 + z3) : (z3 + z1)) / 2)
          || (edge !== 1 && bad(height((x1 + x2) / 2, (y1 + y2) / 2) - (z1 + z2) / 2))
          || (edge !== 2 && bad(height((x2 + x3) / 2, (y2 + y3) / 2) - (z2 + z3) / 2))
          || (edge !== 3 && bad(height((x3 + x1) / 2, (y3 + y1) / 2) - (z3 + z1) / 2))
          || bad(height((x1 + x2 + x3) / 3, (y1 + y2 + y3) / 3) - (z1 + z2 + z3) / 3);
      }
      if (!split || stack.length > 1.2e6) {
        const i = k1 >= 0 ? (ids[k1] >= 0 ? ids[k1] : (ids[k1] = vertex(m, x1, y1, z1 + lift))) : vertex(m, x1, y1, z1 + lift);
        const j = k2 >= 0 ? (ids[k2] >= 0 ? ids[k2] : (ids[k2] = vertex(m, x2, y2, z2 + lift))) : vertex(m, x2, y2, z2 + lift);
        const k = k3 >= 0 ? (ids[k3] >= 0 ? ids[k3] : (ids[k3] = vertex(m, x3, y3, z3 + lift))) : vertex(m, x3, y3, z3 + lift);
        m.indices.push(i, j, k);
        continue;
      }
      if (Number.isNaN(mz)) mz = height(mx, my);
      if (edge === 1) stack.push(x1, y1, z1, k1, mx, my, mz, -1, x3, y3, z3, k3, mx, my, mz, -1, x2, y2, z2, k2, x3, y3, z3, k3);
      else if (edge === 2) stack.push(x1, y1, z1, k1, x2, y2, z2, k2, mx, my, mz, -1, x1, y1, z1, k1, mx, my, mz, -1, x3, y3, z3, k3);
      else stack.push(x1, y1, z1, k1, x2, y2, z2, k2, mx, my, mz, -1, mx, my, mz, -1, x2, y2, z2, k2, x3, y3, z3, k3);
    }
  }
}

/** A height function memoised on a 1 cm grid of its arguments (the drape asks the same points many times). */
export function memoHeight(height: HeightFn): HeightFn {
  const cache = new Map<number, number>();
  return (x, y) => {
    const k = (Math.round(x * 100) + 8_388_608) * 16_777_216 + (Math.round(y * 100) + 8_388_608);
    let z = cache.get(k);
    if (z === undefined) { z = height(x, y); cache.set(k, z); }
    return z;
  };
}

/** Douglas–Peucker on an open polyline, `tol` metres. */
export function simplifyLine(pts: readonly Vec2[], tol: number): Vec2[] {
  if (pts.length <= 2) return pts.map(p => [p[0], p[1]] as Vec2);
  const keep = new Array<boolean>(pts.length).fill(false);
  keep[0] = true; keep[pts.length - 1] = true;
  const todo: [number, number][] = [[0, pts.length - 1]];
  while (todo.length) {
    const [a, b] = todo.pop()!;
    if (b - a < 2) continue;
    const p = pts[a], q = pts[b], dx = q[0] - p[0], dy = q[1] - p[1], l = Math.hypot(dx, dy);
    let worst = 0, at = -1;
    for (let i = a + 1; i < b; i++) {
      const d = l > 1e-9 ? Math.abs((pts[i][0] - p[0]) * dy - (pts[i][1] - p[1]) * dx) / l : Math.hypot(pts[i][0] - p[0], pts[i][1] - p[1]);
      if (d > worst) { worst = d; at = i; }
    }
    if (worst > tol && at > 0) { keep[at] = true; todo.push([a, at], [at, b]); }
  }
  return pts.filter((_, i) => keep[i]).map(p => [p[0], p[1]] as Vec2);
}

/**
 * Point lookup over the roads-v1 polygons of a cell neighbourhood (parks.ts SurfaceIndex over RoadSurface
 * records). Polygons [0, own) are the first cell's: the ones its build draws.
 */
/** Largest footway polygon between parking bays that draws as street (RoadIndex.parkingIslands). */
export const PARKING_ISLAND_MAX_M2 = 40;
/** Largest footway polygon across a carriageway at a crossing that draws as the carriageway (RoadIndex.crossingStrips). */
export const CROSSING_STRIP_MAX_M2 = 120;
/** A crossing strip's edges against the carriageway run across the road: within this of the road's normal. */
export const CROSS_EDGE_DEG = 30;
export class RoadIndex extends SurfaceIndex<RoadSurface> {
  /** `within`: the neighbours' polygons only where the build can ask (the cell, its own ways' reach): earcut of the full 3×3 was a fifth of the roads cost. */
  constructor(cells: readonly (RoadCell | null | undefined)[], within?: readonly [number, number, number, number], deferred = false) { super(cells, () => true, within, deferred); }
  /** The same index built a step per task (`pace` between steps). */
  static paced(cells: readonly (RoadCell | null | undefined)[], within: readonly [number, number, number, number] | undefined, pace: () => Promise<void>): Promise<RoadIndex> {
    return SurfaceIndex.pacedSteps(new RoadIndex(cells, within, true), pace);
  }

  /** Meshes the runtime overrides (parkingIslands): polygon id → mesh. */
  private readonly meshOver = new Map<number, RoadMesh>();
  /**
   * The mesh polygon `k` is drawn with: the extract's (which decides a fietsstraat's red per section, roadCells
   * fietsstraatSection), unless parkingIslands overrode it.
   */
  mesh(k: number): RoadMesh { return this.meshOver.get(k) ?? this.records[k].k; }

  /** Classes the runtime overrides (parkingIslands): polygon id → class drawn. */
  private readonly classOver = new Map<number, RoadClass>();
  /** The class polygon `k` is drawn and probed as (the extract's, unless overridden). */
  drawClass(k: number): RoadClass { return this.classOver.get(k) ?? this.records[k].c; }
  /**
   * Rijbaan sections the extract paints red as a fietsstraat (roadCells fietsstraatSection) where the orthophoto shows
   * grey asphalt (photoEvidence greyFiets: one interior point per section): drawn as asphalt. Lane roads-lanes
   * 2026-10-23: the Marnixstraat busway by the Frederik Hendrikplantsoen read 44 % red in the photo against 77 % on the
   * fietspad beside it. Returns the sections turned grey.
   */
  greyFietsstraat(points: readonly Vec2[]): number {
    let n = 0;
    for (const p of points) {
      const k = this.findAtLevel(p[0], p[1], false);
      if (k < 0 || this.records[k].h !== 0 || this.records[k].c !== 'carriage' || this.mesh(k) !== 'cycle') continue;
      this.meshOver.set(k, 'asphalt'); n++;
    }
    return n;
  }

  /**
   * Small footway polygons between parking bays (the pale islands and tree pits between the bays of a quay street)
   * draw as part of the street: the parking bays' mesh, at road height, without kerbs. User 2026-10-16 on the
   * Prinsengracht by the Pulitzer: "I don't think we need to draw parking spots" — every bay read as a stripe
   * because the islands between them were raised pale paving with granite kerb lines. A foot polygon of at most
   * `maxArea` m² whose perimeter borders parking for at least `minShare` of its length. Returns the count.
   */
  parkingIslands(maxArea = PARKING_ISLAND_MAX_M2, minShare = 0.5): number {
    let n = 0;
    for (let k = 0; k < this.records.length; k++) {
      const r = this.records[k];
      if (r.c !== 'foot' || this.classOver.has(k)) continue;
      const ring = this.ringsOf(k)[0];
      if (!ring || ring.length < 3) continue;
      let a2 = 0;
      for (let i = 0; i < ring.length; i++) { const p = ring[i], q = ring[(i + 1) % ring.length]; a2 += p[0] * q[1] - q[0] * p[1]; }
      if (Math.abs(a2) / 2 > maxArea) continue;
      let total = 0, park = 0; const parkMesh = new Map<RoadMesh, number>();
      for (let i = 0; i < ring.length; i++) {
        const p = ring[i], q = ring[(i + 1) % ring.length], len = Math.hypot(q[0] - p[0], q[1] - p[1]);
        if (len < 1e-6) continue;
        total += len;
        const mx = (p[0] + q[0]) / 2, my = (p[1] + q[1]) / 2, nx = -(q[1] - p[1]) / len, ny = (q[0] - p[0]) / len;
        for (const s of [1, -1]) {
          const hit = this.findAll(mx + s * nx * 0.3, my + s * ny * 0.3).find(j => j !== k);
          if (hit !== undefined && this.records[hit].c === 'parking') { park += len; parkMesh.set(this.mesh(hit), (parkMesh.get(this.mesh(hit)) ?? 0) + len); break; }
        }
      }
      if (!total || park / total < minShare) continue;
      const mesh = [...parkMesh.entries()].sort((x, y) => y[1] - x[1])[0][0];
      this.classOver.set(k, 'parking'); this.meshOver.set(k, mesh); n++;
    }
    return n;
  }

  /**
   * Footway strips across a carriageway at a mapped crossing draw as the carriageway (its mesh, at road height,
   * without kerbs), so the zebra is painted on them. BGT maps many crossings as a `voetpad` polygon across the road
   * (Leidseplein: every zebra of the plein), which drew as a raised pale pavement strip with granite kerbs across the
   * road and kept the zebra off it (crossing audit 2026-10-17, user: "crossings sit on cobbles and in odd places").
   * A foot polygon of at most `maxArea` m² that holds a crossing point `p` (on the road way, `r` the road's direction
   * there), and borders a carriageway along edges running across the road (within CROSS_EDGE_DEG of the normal to
   * `r`) on both sides of the point, at least `minEdge` metres each, and whose edges along the road meet no
   * carriageway for at least half their length (a strip runs kerb to kerb; a refuge island has road beside it and
   * stays). Returns the count. The road beside the strip may be any road-level class (KERB_LOW_CLASSES): BGT maps the
   * zebra across a fietspad and between a cycle lane and the carriageway as voetpad strips too (user 2026-10-30 at the
   * Prins Hendrikkade by Arcam: pale kerbed strips cut every zebra into pieces); the strip takes the class and mesh it
   * borders most.
   */
  crossingStrips(points: readonly { p: Vec2; r: Vec2 }[], maxArea = CROSSING_STRIP_MAX_M2, minEdge = 1.5): number {
    let n = 0;
    const done = new Set<number>(), cosMax = Math.cos((90 - CROSS_EDGE_DEG) * Math.PI / 180);
    for (const { p, r } of points) {
      for (const k of this.findAll(p[0], p[1])) {
        if (done.has(k) || this.records[k].h !== 0 || this.drawClass(k) !== 'foot') continue;
        const ring = this.ringsOf(k)[0];
        if (!ring || ring.length < 3) continue;
        let a2 = 0;
        for (let i = 0; i < ring.length; i++) { const a = ring[i], b = ring[(i + 1) % ring.length]; a2 += a[0] * b[1] - b[0] * a[1]; }
        if (Math.abs(a2) / 2 > maxArea) continue;
        const side = [0, 0], meshLen = new Map<RoadMesh, number>(), clsLen = new Map<RoadClass, number>(), along = [0, 0];
        for (let i = 0; i < ring.length; i++) {
          const a = ring[i], b = ring[(i + 1) % ring.length], len = Math.hypot(b[0] - a[0], b[1] - a[1]);
          if (len < 1e-6) continue;
          const ux = (b[0] - a[0]) / len, uy = (b[1] - a[1]) / len;
          const mx = (a[0] + b[0]) / 2, my = (a[1] + b[1]) / 2, nx = -uy, ny = ux;
          if (Math.abs(ux * r[0] + uy * r[1]) > cosMax) {
            // An edge along the road: a strip meets the pavement or a cycle path here; an island the carriageway.
            if (Math.abs(ux * r[0] + uy * r[1]) >= Math.cos(CROSS_EDGE_DEG * Math.PI / 180)) {
              along[1] += len;
              if ([1, -1].some(s => { const hit = this.findAll(mx + s * nx * 0.3, my + s * ny * 0.3).find(j => j !== k && this.records[j].h === 0); return hit !== undefined && this.drawClass(hit) === 'carriage'; })) along[0] += len;
            }
            continue;
          }
          for (const s of [1, -1]) {
            const hit = this.findAll(mx + s * nx * 0.3, my + s * ny * 0.3).find(j => j !== k && this.records[j].h === 0);
            if (hit === undefined || !isLow(this.drawClass(hit))) continue;
            // Which side of the crossing point (along the road) the edge lies on.
            side[(mx - p[0]) * r[0] + (my - p[1]) * r[1] >= 0 ? 0 : 1] += len;
            meshLen.set(this.mesh(hit), (meshLen.get(this.mesh(hit)) ?? 0) + len);
            clsLen.set(this.drawClass(hit), (clsLen.get(this.drawClass(hit)) ?? 0) + len);
            break;
          }
        }
        if (side[0] < minEdge || side[1] < minEdge || along[0] > 0.5 * along[1]) continue;
        const mesh = [...meshLen.entries()].sort((x, y) => y[1] - x[1])[0][0], cls = [...clsLen.entries()].sort((x, y) => y[1] - x[1])[0][0];
        this.classOver.set(k, cls); this.meshOver.set(k, mesh); done.add(k); n++;
      }
    }
    return n;
  }

  private fast: { raster: SurfaceRaster; box: readonly [number, number, number, number] } | null = null;
  /**
   * A raster of polygon ids over `box` at `res` (FAST_RES_M) that answers the point lookups inside it (a texel
   * takes the polygon under its centre): the street pass asks for the class under every paint dash, rail station
   * and band station, and an exact ring test against a 3,000-vertex pavement polygon per ask made the pass seconds
   * long. Outside the box, and for a deck/ground level the texel's polygon does not have, the exact test runs.
   */
  prepareFast(box: readonly [number, number, number, number], res = FAST_RES_M): SurfaceRaster {
    const raster = this.raster(box, res);
    this.fast = { raster, box };
    return raster;
  }

  /**
   * The polygon under (x, y) at the wanted level: `bridge` prefers a deck polygon (h ≥ 1), else a ground one
   * (h = 0); when none at that level, whatever lies there. -1: none.
   */
  findAtLevel(x: number, y: number, bridge = false): number {
    const f = this.fast;
    if (f && x >= f.box[0] && x < f.box[2] && y >= f.box[1] && y < f.box[3]) {
      const k = f.raster.find(x, y);
      if (k < 0) return -1;
      const h = this.records[k].h;
      if (bridge ? h >= 1 : h === 0) return k;
    }
    const all = this.findAll(x, y);
    if (!all.length) return -1;
    const want = all.find(k => (bridge ? this.records[k].h >= 1 : this.records[k].h === 0));
    return want ?? all[0];
  }
  /** Any polygon under the point (the fast raster inside its box). */
  findFast(x: number, y: number): number {
    const f = this.fast;
    if (f && x >= f.box[0] && x < f.box[2] && y >= f.box[1] && y < f.box[3]) return f.raster.find(x, y);
    return this.find(x, y);
  }
  classAt(x: number, y: number, bridge = false): RoadClass | null { const k = this.findAtLevel(x, y, bridge); return k < 0 ? null : this.drawClass(k); }
  heightAt(x: number, y: number, bridge = false): number | null { const k = this.findAtLevel(x, y, bridge); return k < 0 ? null : this.records[k].h; }
  meshAt(x: number, y: number, bridge = false): RoadMesh | null { const k = this.findAtLevel(x, y, bridge); return k < 0 ? null : this.mesh(k); }
  /** May road paint, a rail or a lane ribbon lie here: a carriageway or parking polygon, or no survey at all (the bands' fallback). */
  onRoad(x: number, y: number, bridge = false): boolean { const c = this.classAt(x, y, bridge); return c === null || c === 'carriage' || c === 'parking'; }
  /** Is any deck polygon (h ≥ 1) under the point? */
  onDeck(x: number, y: number): boolean { return this.findAll(x, y).some(k => this.records[k].h >= 1); }
  /** A ground-level (h 0) polygon (of one of `classes`, when given) here (bridgeGaps: a widened deck or a dry way deck stops at it). */
  onGround(x: number, y: number, classes?: ReadonlySet<string>): boolean { return this.findAll(x, y).some(k => this.records[k].h === 0 && (!classes || classes.has(this.drawClass(k)))); }
  /**
   * Is a band's station covered by the survey: any polygon under the point is the surface there (a footway band over
   * a rijbaan, a carriageway band over a voetpad: the survey wins), except a cycle band over a rijbaan or parkeervlak,
   * which stays as the painted lane on the road (the data lane: cycleway ways are fietspad for ~60 % of their length
   * and cross rijbaan for the rest). Off the survey nothing is covered (streets.ts coverCuts).
   */
  coversBand(x: number, y: number, surface: RoadMesh, bridge = false): boolean {
    const c = this.classAt(x, y, bridge);
    if (c === null) return false;
    if (surface === 'cycle') return c !== 'carriage' && c !== 'parking';
    return true;
  }
  /** Does the index hold any deck polygon at all (the deck-top rule asks before probing)? */
  get hasDecks(): boolean { return this.records.some(r => r.h >= 1); }
}

export interface RoadBuildStats {
  /** Polygons drawn, by class. */
  drawn: Record<RoadClass, number>;
  /** Deck polygons (h ≥ 1) drawn on the deck surface. */
  onDeck: number;
  /** Deck polygons over neither a measured deck nor water: not drawn. */
  skippedHigh: number;
  /** Polygons too small to triangulate. */
  degenerate: number;
  kerbs: number;
  kerbM: number;
  /** Kerb lines whose lower side could not be told (no low class on exactly one side): drawn without a face. */
  kerbUnsided: number;
  /** bridgeCarry (deckCarry.ts): deck polygons drawn only because of the carry; ground polygons cut under a low deck (of them, wholly under it); kerb runs cut. */
  carried?: number;
  groundCut?: number;
  groundUnder?: number;
  kerbCut?: number;
  /** redDedupe: pavement-level polygons cut under a red fietspad of their own level. */
  redCut?: number;
  bollards: number;
  ms: number;
}

export type RoadLayer = RoadMesh | 'brick' | 'kerb' | 'bollard' | 'lawn';

/**
 * The layer a polygon draws in: its mesh, except klinker inritten and parking bays (and the footway islands drawn
 * with them), which take the muted grey `brick` (road look v2, 2026-10-16: on the orthophoto they read as greyish
 * brick close to the pavement; drawn as the klinker carriageway they were saturated brown wedges across pavements).
 */
export function surfaceLayer(cls: RoadClass, mesh: RoadMesh): RoadLayer {
  // The park grass material (the `lawn` layer parks-v1 draws) for green verges and grass islands (roads lane R1).
  if (mesh === 'grass') return 'lawn';
  // One material per level (lane road-look-continuity 2026-10-29, user: "why isn't the grey continuous?"). Every
  // pavement-level class draws the one paving: within the Witte de Withstraat crop the islands, berms, squares and
  // inritten drew asphalt, brick and paving at the sidewalk top, and the joins between them read as pale wedges at
  // every corner. The kerb (the level step) is the edge the rider reads; the survey's surface under a pavement is not.
  // Issue #52's island rule (asphalt islands as raised paving) is the special case of this one.
  if (PAVEMENT_LEVEL.has(cls)) return 'paving';
  // Carriage level: asphalt or klinker by surface alone, parking bays included (no separate brick, which drew a third
  // grey beside the road and the pavement); a fietsstraat section stays red, gravel stays gravel.
  return mesh === 'paving' ? 'asphalt' : mesh;
}
/**
 * A big asphalt `square` is a carriageway the survey filed as terrain (lane R2-D 2026-11-13, feedback a5806a8e "ground
 * still looks really bad", the Lelylaan / A10 interchange): Rijkswaterstaat's L0002 `onbegroeidterreindeel` polygons of
 * `gesloten verharding` with no function cover whole slip roads, lanes with arrows on the 2025 photo, and roads-v1 files
 * them as `square` (ancillaryClass), which drew in the one pale pavement material: dark asphalt slip roads read as pale
 * footways between the grass strips. A square of asphalt of at least this area draws as asphalt (275 ha of `square/asphalt`
 * city-wide, 199 ha of it in the 496 polygons over 1,000 m²; asphalt squares under 800 m² stay pavement-level grey, as
 * the one-material-per-level rule of 2026-10-29 has it). The kerb and the lift are the square's own.
 */
export const ASPHALT_SQUARE_MIN_M2 = 800;
export function ringAreaM2(ring: readonly (readonly [number, number])[]): number {
  let a = 0;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) a += ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1];
  return Math.abs(a) / 2;
}
/** The classes drawn at the sidewalk top (ROAD_LIFT SIDEWALK_TOP): one material, `paving`, unless green. */
export const PAVEMENT_LEVEL: ReadonlySet<RoadClass> = new Set<RoadClass>(['foot', 'pedestrian', 'driveway', ...ANCILLARY_CLASSES]);

export interface RoadBuildInput {
  /** The land surface the h = 0 polygons drape on (groundCell `onLand`). */
  height: HeightFn;
  /** Ground polygons (h 0) and their kerbs drape on this when given (groundCell onStreet: no lift under a way deck's hole ranges, lane F1b); absent: `height`. */
  streetHeight?: HeightFn;
  /** The riding surface with the decks (GroundSurface.height), for h ≥ 1 polygons; see `deckLevelHeight`. */
  deckHeight: HeightFn;
  /** 1 on a measured deck, 0 off every deck (GroundSurface.deckWeight). */
  deckWeight: (x: number, y: number) => number;
  overWater: (x: number, y: number) => boolean;
  /** Inside an unmeasured (flat) deck footprint (bridgeGaps, issue #178): a deck polygon there drapes on the riding surface, as the footprint's top does. Absent: flat footprints carry no deck polygon (the pre-fix build). */
  onFlatDeck?: (x: number, y: number) => boolean;
  /** bridgeGaps (issue #178): a deck polygon whose interior point misses every deck is still drawn when DECK_SHARE_MIN of it lies on one, without its triangles over a ground polygon. */
  bridgeGaps?: boolean;
  /**
   * The carry across bridges (deckCarry.ts, lane R5-C1 issue #262): deck polygons low over the ground polygons they
   * overlap are drawn whole and cut those out from under them; skipped deck polygons at a bridge are drawn on the
   * riding surface. Absent / false: the build before it (`?bridgeCarry=0`).
   */
  bridgeCarry?: boolean;
  /**
   * redDedupe (lane R5-C1, issue #262): the BGT fietspad's drape float bounded like the carriageway's (RED_CYCLE_TOL),
   * and a pavement-level polygon the survey overlaps with a fietspad of its own level cut under it. Absent / false: as
   * before (`?redDedupe=0`).
   */
  redDedupe?: boolean;
  lod: 0 | 1;
  /** Ground drape sag / float tolerance overrides for the road classes (measurement scripts); the defaults are DRAPE_TOL. */
  drapeTol?: number;
  drapeFloatTol?: number;
  /** Lane G1 item B: the min-area gate only for compact triangles (ROAD_STRIP_GATE_STEPS); default off here, buildCell passes it on (`?roadStrips=0` off). */
  roadStrips?: boolean;
  /**
   * 'touch': a cell far from the rider on a touch device (gameGround.ts, CANAL-RECALL-7). The polygons, kerbs and lines
   * are all still drawn (the footprint is unchanged); the drape and the kerb stations are coarser, as the relief's
   * shape barely shows at that distance.
   */
  detail?: 'full' | 'touch';
  /** Canal-side test for the Amsterdammertjes (streets.ts bollards); near ring only. */
  canalSide?: (x: number, y: number) => boolean;
  /**
   * The relief's measured sample spacing under a point (GroundSurface.dataStepAt): the drape splits no finer than
   * this, since detail between samples is interpolation (the coarse ring's 4 m tiles upsampled to the 2 m grid).
   */
  dataStep?: (x: number, y: number) => number;
}

/**
 * A height for the deck polygons: the riding surface, never under the deck's own level at that station (beside
 * the road's half-width GroundSurface.height falls back to the relief, which under a bridge is the canal; a
 * voetpad polygon at the parapet would drape into the water). The decks whose box meets `rect` ± `pad`.
 */
export function deckLevelHeight(surface: GroundSurface, rect: readonly [number, number, number, number], pad = 60): HeightFn {
  const decks = surface.decks.filter(d => { const [x0, y0, x1, y1] = d.profile.bbox; return !(x1 < rect[0] - pad || x0 > rect[2] + pad || y1 < rect[1] - pad || y0 > rect[3] + pad); });
  const P = 15;
  return (x, y) => {
    let z = surface.height(x, y);
    for (const d of decks) {
      const [x0, y0, x1, y1] = d.profile.bbox;
      if (x < x0 - P || x > x1 + P || y < y0 - P || y > y1 + P) continue;
      const at = GroundSurface.locate(d, x, y);
      if (at.d === Infinity) continue;
      z = Math.max(z, at.z);
    }
    return z;
  };
}

/**
 * The road meshes of one cell: the index's own polygons [0, own) and the cell's kerb lines. Returns the layers,
 * the stats and the ids of the own polygons that were not drawn (the land under them must stay).
 */
/** A deck polygon is drawn when at least this share of its area lies on a deck or over water (bridgeGaps, deckShare). */
export const DECK_SHARE_MIN = 0.25;
/**
 * bridgeGaps (issue #178): a deck-level polygon whose interior point lies off every deck (a long survey polygon over a
 * flat footprint and its ramp, a polygon wider than the deck) is drawn when DECK_SHARE_MIN of its area (by triangle
 * centroids) lies on a deck, without the triangles whose centroid lies over a ground polygon (never a bridge painted
 * over the street under it). Null: not drawn.
 */
export function deckShare(flat: readonly number[], tris: readonly number[], onDeck: (x: number, y: number) => boolean, overGround: (x: number, y: number) => boolean): number[] | null {
  let total = 0, on = 0;
  const kept: number[] = [];
  for (let t = 0; t < tris.length; t += 3) {
    const a = tris[t] * 2, b = tris[t + 1] * 2, c = tris[t + 2] * 2;
    const area = Math.abs((flat[b] - flat[a]) * (flat[c + 1] - flat[a + 1]) - (flat[c] - flat[a]) * (flat[b + 1] - flat[a + 1])) / 2;
    const cx = (flat[a] + flat[b] + flat[c]) / 3, cy = (flat[a + 1] + flat[b + 1] + flat[c + 1]) / 3;
    total += area;
    const deck = onDeck(cx, cy);
    if (deck) on += area;
    if (deck || !overGround(cx, cy)) kept.push(tris[t], tris[t + 1], tris[t + 2]);
  }
  return total > 0 && on >= DECK_SHARE_MIN * total && kept.length ? kept : null;
}

export function buildRoadSurfaces(cell: RoadCell, index: RoadIndex, input: RoadBuildInput): { layers: Partial<Record<RoadLayer, MeshArrays>>; stats: RoadBuildStats; skipped: Set<number>; /** bridgeCarry: a deck polygon of any cell of the index that is drawn low over the ground (the land under it may go). */ lowDeck?: (k: number) => boolean } {
  const t0 = Date.now();
  const layers: Partial<Record<RoadLayer, MeshArrays>> = {};
  // The kerb mesh carries vertex colours (white: the kerb material's own tone; KERB_SHADOW_TINT: the shadow line).
  const get = (l: RoadLayer) => (layers[l] ??= emptyMesh(l === 'kerb'));
  const stats: RoadBuildStats = { drawn: { carriage: 0, foot: 0, cycle: 0, pedestrian: 0, parking: 0, driveway: 0, island: 0, berm: 0, verge: 0, square: 0 }, onDeck: 0, skippedHigh: 0, degenerate: 0, kerbs: 0, kerbM: 0, kerbUnsided: 0, bollards: 0, ms: 0 };
  const skipped = new Set<number>();
  const far = input.lod === 1;
  /** A `touch` cell: coarser drape tolerances and kerb stations (RoadBuildInput.detail). */
  const touch = input.detail === 'touch';
  const tolScale = touch ? TOUCH_DRAPE_TOL_SCALE : 1;
  const minEdgeM = DRAPE_MIN_EDGE_M * (touch ? TOUCH_MIN_EDGE_SCALE : 1);
  // The drape carries each corner's height and asks once per corner and tested point (drapeAdaptive); a 1 cm memo
  // of the heights on top cost more in Map lookups than the land grid's own lookup (the deck surface keeps it).
  const landHeight = input.height, deckHeight = memoHeight(input.deckHeight), streetHeight = input.streetHeight ?? landHeight;
  /** The surface a deck polygon (or a kerb on one) drapes on, or null when nothing carries it. */
  const deckSurface = (p: Vec2 | null): HeightFn | null => (p && (input.deckWeight(p[0], p[1]) > 0 || input.overWater(p[0], p[1]) || !!input.onFlatDeck?.(p[0], p[1])) ? deckHeight : null);
  /** The build without the carry for a deck polygon: drawn on what, with which triangles (null: skipped). */
  const groundAt = (x: number, y: number) => index.findAll(x, y).some(j => index.records[j].h === 0);
  const deckBefore = (k: number): readonly number[] | null => {
    const { flat, tris } = index.flatOf(k);
    if (deckSurface(interiorPoint(index.ringsOf(k)))) return tris;
    return input.bridgeGaps ? deckShare(flat, tris, (x, y) => !!deckSurface([x, y]), groundAt) : null;
  };
  // bridgeCarry (deckCarry.ts): one decision per deck polygon of the index, the same in every cell that sees it.
  const carry = input.bridgeCarry === true && !far;
  /** redDedupe: the fietspad's bounded float, the pavement cut under it. */
  const redOwn = input.redDedupe === true;
  const carryIn: CarryInput = { land: landHeight, deck: deckHeight, overWater: input.overWater, carried: (x, y) => !!deckSurface([x, y]) };
  const decisions = new Map<number, { d: DeckDecision; before: readonly number[] | null }>();
  const decide = (k: number) => {
    let e = decisions.get(k);
    if (!e) { const before = deckBefore(k); e = { d: deckDecision(index, k, carryIn, !!before), before }; decisions.set(k, e); }
    return e;
  };
  /** Deck polygons (any cell) drawn low over the ground, with their boxes: the ground under them is cut. */
  const lowDecks: { k: number; box: [number, number, number, number] }[] = [];
  if (carry) for (let k = 0; k < index.records.length; k++) {
    if (index.records[k].h < 1) continue;
    const ring = index.ringsOf(k)[0];
    if (!ring || ring.length < 3) continue;
    const box: [number, number, number, number] = [Infinity, Infinity, -Infinity, -Infinity];
    for (const p of ring) { box[0] = Math.min(box[0], p[0]); box[1] = Math.min(box[1], p[1]); box[2] = Math.max(box[2], p[0]); box[3] = Math.max(box[3], p[1]); }
    // Only a deck polygon that overlaps a ground polygon can be low; the decision walks its triangles.
    const d = decide(k).d;
    if (d.draw && d.low) lowDecks.push({ k, box });
  }
  const lowDeckSet = new Set(lowDecks.map(l => l.k));
  /** redDedupe: the red fietspad polygons' boxes by level (own and neighbours'), shrunk by RED_OVERLAP_MIN_M. */
  const redBoxes: { h: number; box: [number, number, number, number] }[] = [];
  if (redOwn) for (let j = 0; j < index.records.length; j++) {
    if (index.drawClass(j) !== 'cycle' || index.mesh(j) !== 'cycle') continue;
    const ring = index.ringsOf(j)[0];
    if (!ring || ring.length < 3) continue;
    const b: [number, number, number, number] = [Infinity, Infinity, -Infinity, -Infinity];
    for (const p of ring) { b[0] = Math.min(b[0], p[0]); b[1] = Math.min(b[1], p[1]); b[2] = Math.max(b[2], p[0]); b[3] = Math.max(b[3], p[1]); }
    redBoxes.push({ h: index.records[j].h, box: [b[0] + RED_OVERLAP_MIN_M, b[1] + RED_OVERLAP_MIN_M, b[2] - RED_OVERLAP_MIN_M, b[3] - RED_OVERLAP_MIN_M] });
  }
  /** The red boxes of level `h` overlapping the polygon's box (`flat` its vertices), shrunk past a shared edge. */
  const redBoxesOver = (flat: readonly number[], h: number): [number, number, number, number][] => {
    if (!redBoxes.length) return [];
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (let i = 0; i < flat.length; i += 2) { x0 = Math.min(x0, flat[i]); y0 = Math.min(y0, flat[i + 1]); x1 = Math.max(x1, flat[i]); y1 = Math.max(y1, flat[i + 1]); }
    x0 += RED_OVERLAP_MIN_M; y0 += RED_OVERLAP_MIN_M; x1 -= RED_OVERLAP_MIN_M; y1 -= RED_OVERLAP_MIN_M;
    return redBoxes.filter(r => r.h === h && r.box[0] < x1 && r.box[2] > x0 && r.box[1] < y1 && r.box[3] > y0).map(r => r.box);
  };
  /** Inside a low deck polygon by more than KERB_ON_DECK_EDGE_M from its rings (a ground kerb the deck covers). */
  const insideLowDeck = (x: number, y: number) => lowDecks.length > 0 && index.findAll(x, y).some(j => lowDeckSet.has(j) && ringDistance(index.ringsOf(j), x, y) > KERB_ON_DECK_EDGE_M);
  for (let k = 0; k < index.own; k++) {
    const rec = index.records[k];
    // The index's own earcut of the polygon (SurfaceIndex flatOf): the raster and the drawn mesh are the same triangles.
    const { flat, tris: tris0 } = index.flatOf(k);
    if (flat.length < 6) { stats.degenerate++; skipped.add(k); continue; }
    if (!tris0.length) { stats.degenerate++; skipped.add(k); continue; }
    let height = streetHeight;
    let tris = tris0;
    let pieces: Vec2[][][] | null = null;
    if (rec.h >= 1 && carry) {
      // bridgeCarry: drawn whole when low over the ground (the ground is cut under it), else as before; carried at a bridge.
      const { d, before } = decide(k);
      if (!d.draw) { stats.skippedHigh++; skipped.add(k); continue; }
      tris = d.whole || !before ? tris0 : before;
      if (d.carriedOnly) stats.carried = (stats.carried ?? 0) + 1;
      height = deckHeight;
      stats.onDeck++;
    } else if (rec.h >= 1) {
      let on = deckSurface(interiorPoint(index.ringsOf(k)));
      if (!on && input.bridgeGaps) {
        const kept = deckShare(flat, tris, (x, y) => !!deckSurface([x, y]), (x, y) => index.findAll(x, y).some(j => index.records[j].h === 0));
        if (kept) { tris = kept; on = deckHeight; }
      }
      if (!on) { stats.skippedHigh++; skipped.add(k); continue; }
      height = on;
      stats.onDeck++;
    }
    // redDedupe: a pavement-level polygon the survey overlaps with a red fietspad of its own level (the Beltbrug's berm
    // over the fietspad, 25 m² of grey on the red) gives way to the red; triangle centroids find the overlap.
    const redCutters: number[] = [];
    const nearRed = redOwn && PAVEMENT_LEVEL.has(index.drawClass(k)) ? redBoxesOver(flat, rec.h) : [];
    if (nearRed.length) {
      const seen = new Set<number>();
      for (let t = 0; t < tris0.length; t += 3) {
        const a = tris0[t] * 2, b = tris0[t + 1] * 2, c = tris0[t + 2] * 2;
        const tx0 = Math.min(flat[a], flat[b], flat[c]), tx1 = Math.max(flat[a], flat[b], flat[c]), ty0 = Math.min(flat[a + 1], flat[b + 1], flat[c + 1]), ty1 = Math.max(flat[a + 1], flat[b + 1], flat[c + 1]);
        if (!nearRed.some(r => r[0] < tx1 && r[2] > tx0 && r[1] < ty1 && r[3] > ty0)) continue;
        const cx = (flat[a] + flat[b] + flat[c]) / 3, cy = (flat[a + 1] + flat[b + 1] + flat[c + 1]) / 3;
        // The centroid, the edge midpoints and half-way to each corner (a thin overlap along an edge misses the centroid).
        const probes: Vec2[] = [[cx, cy], [(flat[a] + flat[b]) / 2, (flat[a + 1] + flat[b + 1]) / 2], [(flat[b] + flat[c]) / 2, (flat[b + 1] + flat[c + 1]) / 2], [(flat[c] + flat[a]) / 2, (flat[c + 1] + flat[a + 1]) / 2],
          [(cx + flat[a]) / 2, (cy + flat[a + 1]) / 2], [(cx + flat[b]) / 2, (cy + flat[b + 1]) / 2], [(cx + flat[c]) / 2, (cy + flat[c + 1]) / 2]];
        for (const [px, py] of probes) for (const j of index.findAll(px, py)) {
          if (j === k || seen.has(j) || index.records[j].h !== rec.h || index.drawClass(j) !== 'cycle' || index.mesh(j) !== 'cycle') continue;
          // On the shared edge of two neighbours (no overlap): not a cutter (the polygon difference would change nothing).
          if (ringDistance(index.ringsOf(j), px, py) <= RED_OVERLAP_MIN_M || ringDistance(index.ringsOf(k), px, py) <= RED_OVERLAP_MIN_M) continue;
          seen.add(j); redCutters.push(j);
        }
      }
    }
    if (rec.h === 0 && (lowDecks.length || redCutters.length)) {
      // bridgeCarry: a ground polygon under a low deck polygon loses the part under it (a polygon difference).
      const rings = index.ringsOf(k), ring = rings[0];
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      for (const p of ring) { x0 = Math.min(x0, p[0]); y0 = Math.min(y0, p[1]); x1 = Math.max(x1, p[0]); y1 = Math.max(y1, p[1]); }
      const cutters = [...lowDecks.filter(l => l.box[0] < x1 && l.box[2] > x0 && l.box[1] < y1 && l.box[3] > y0).map(l => index.ringsOf(l.k)), ...redCutters.map(j => index.ringsOf(j))];
      pieces = cutters.length ? cutUnderDecks(rings, cutters) : null;
      if (pieces && redCutters.length) stats.redCut = (stats.redCut ?? 0) + 1;
      if (pieces) {
        stats.groundCut = (stats.groundCut ?? 0) + 1;
        // Wholly under the deck: nothing of it is drawn; the deck covers it (not `skipped`: the land under it may go).
        if (!pieces.length) { stats.groundUnder = (stats.groundUnder ?? 0) + 1; continue; }
      }
    }
    const cls = index.drawClass(k);
    const layer = get(cls === 'square' && index.mesh(k) === 'asphalt' && ringAreaM2(index.ringsOf(k)[0]) >= ASPHALT_SQUARE_MIN_M2 ? 'asphalt' : surfaceLayer(cls, index.mesh(k)));
    // redDedupe: the red fietspad's float bounded (RED_CYCLE_TOL).
    const redPlane = redOwn && cls === 'cycle' && index.mesh(k) === 'cycle';
    const lift = ROAD_LIFT[cls];
    traceMark(layer, cls === 'carriage' && index.mesh(k) === 'cycle' ? 'fietsstraat' : BGT_SOURCE[cls]);
    if (rec.h >= 1) drapeAdaptive(layer, flat, tris, height, lift, far ? 2 * DECK_DRAPE_MAX_EDGE_M : DECK_DRAPE_MAX_EDGE_M, DECK_DRAPE_TOL_M, 1.5);
    else if (pieces) {
      const tol = redPlane ? RED_CYCLE_TOL : DRAPE_TOL[cls], low = isLow(cls);
      const sagTol = ((low && input.drapeTol) || tol.sag) * tolScale, floatTol = ((low && input.drapeFloatTol) || tol.float) * tolScale;
      for (const piece of pieces) {
        const f = flatten(piece);
        if (f.flat.length < 6) continue;
        const step = input.dataStep?.(f.flat[0], f.flat[1]) ?? 0, coarse = step > DRAPE_MIN_EDGE_M;
        drapeAdaptive(layer, f.flat, earcut(f.flat, f.holes), height, lift, DRAPE_MAX_EDGE_M, sagTol, coarse ? step : minEdgeM, floatTol, coarse ? DRAPE_MIN_AREA_STEPS * step * step : 0, coarse && input.roadStrips ? ROAD_STRIP_GATE_STEPS * step : Infinity);
      }
    } else {
      const tol = redPlane ? RED_CYCLE_TOL : DRAPE_TOL[cls], low = isLow(cls);
      // Where the relief was measured coarser than the drape's own minimum (the 4 m ring), no triangle splits finer
      // than a data sample: not by edge, and not by area, which on a verge strip's slivers is what the edge test misses.
      const step = input.dataStep?.(flat[0], flat[1]) ?? 0, coarse = step > DRAPE_MIN_EDGE_M;
      const sagTol = ((low && input.drapeTol) || tol.sag) * tolScale;
      const floatTol = ((low && input.drapeFloatTol) || tol.float) * tolScale;
      drapeAdaptive(layer, flat, tris, height, lift, far ? 2 * DRAPE_MAX_EDGE_M : DRAPE_MAX_EDGE_M, sagTol, coarse ? step : minEdgeM, far ? Infinity : floatTol, coarse ? DRAPE_MIN_AREA_STEPS * step * step : 0, coarse && input.roadStrips ? ROAD_STRIP_GATE_STEPS * step : Infinity);
    }
    stats.drawn[cls]++;
  }
  // Kerbs: the face toward the lower side, the granite line on the upper edge, posts along canal-side pavements.
  const kerb = get('kerb');
  traceMark(kerb, 'bgtKerb');
  const kerbRuns = (e: readonly number[]): Vec2[][] => {
    const run = decodeKerb(e, touch ? KERB_SIMPLIFY_M * TOUCH_KERB_SIMPLIFY_SCALE : KERB_SIMPLIFY_M);
    if (!lowDecks.length || run.length < 2) return [run];
    // bridgeCarry: a ground-level kerb inside a low deck polygon is not drawn (the ground it divides was cut away). A
    // kerb on a deck polygon's own edge (the deck's kerbs, or a ground kerb meeting the deck) lies on its ring: kept.
    const parts = runsOutside(run, insideLowDeck);
    if (parts.length !== 1 || parts[0].length !== run.length) stats.kerbCut = (stats.kerbCut ?? 0) + 1;
    return parts;
  };
  for (const e of cell.kerbs) for (const run of kerbRuns(e)) {
    if (run.length < 2) continue;
    const st = stations(run), total = st[st.length - 1];
    if (total < 0.3) continue;
    // The sides are probed at the middle 4 m station, as before the relief-adaptive stations.
    const probe = densify(run, KERB_PROBE_STEP_M), mid = Math.floor(probe.length / 2), a = probe[Math.max(0, mid - 1)], b = probe[Math.min(probe.length - 1, mid)];
    const cx = (a[0] + b[0]) / 2, cy = (a[1] + b[1]) / 2, dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1, nx = -dy / l, ny = dx / l;
    const h = index.heightAt(cx, cy) ?? 0, bridge = h >= 1;
    const left = index.classAt(cx + nx * KERB_PROBE_M, cy + ny * KERB_PROBE_M, bridge), right = index.classAt(cx - nx * KERB_PROBE_M, cy - ny * KERB_PROBE_M, bridge);
    // Both sides low: a kerb of a footway island drawn as street (parkingIslands); the street has none there.
    if (isLow(left) && isLow(right)) continue;
    const lowLeft = isLow(left) && !isLow(right), lowRight = isLow(right) && !isLow(left);
    let height = streetHeight;
    if (bridge) { const on = deckSurface([cx, cy]) ?? (carry && index.findAll(cx, cy).some(j => index.records[j].h >= 1 && decide(j).d.draw) ? deckHeight : null); if (!on) continue; height = on; }
    // Decks hump within a span (DECK_DRAPE_MAX_EDGE_M); on land, no finer than the relief was measured.
    const line = bridge ? densifyOnRelief(run, height, KERB_RELIEF_TOL_M, 1, DECK_DRAPE_MAX_EDGE_M)
      : densifyOnRelief(run, height, KERB_RELIEF_TOL_M * (touch ? TOUCH_KERB_RELIEF_SCALE : 1), Math.max(KERB_PROBE_STEP_M / 2, input.dataStep?.(cx, cy) ?? 0), DRAPE_MAX_EDGE_M);
    stats.kerbs++; stats.kerbM += total;
    if (!lowLeft && !lowRight) {
      // No face: the line alone (a kerb between two pavements of different heights the survey does not say).
      stats.kerbUnsided++;
      ribbon(kerb, line, 0, KERB_LINE_M, height, KERB_LINE_Z, { step: Infinity });
      continue;
    }
    const facing: 1 | -1 = lowLeft ? 1 : -1, into = lowLeft ? -1 : 1; // `into`: toward the upper side (way-left is +)
    edgeWall(kerb, line, 0, height, KERB_TOP, KERB_FACE_BOTTOM, facing, { step: Infinity });
    ribbon(kerb, line, into * KERB_LINE_M / 2, KERB_LINE_M, height, KERB_LINE_Z, { step: Infinity });
    // The shadow line on the low side at the face's foot, at the rails' lift over the relief (ROAD_MARK_LIFT.rail).
    // Lane road-look-continuity 2026-10-29: 0.14 m of flat tint was under a pixel from the phone's chase camera, so the
    // level step vanished and the road grey ran into the pavement grey. A 0.45 m ramp from the groove tone at the face
    // to none reads at chase distance and has no hard outer edge. `into` > 0: the upper side is the ribbon's left, so
    // the face (and the dark end) is the ramp's left edge.
    const lowCls = (lowLeft ? left : right)!, lowMesh = index.meshAt(cx - into * nx * KERB_PROBE_M, cy - into * ny * KERB_PROBE_M, bridge) ?? 'asphalt';
    const end = KERB_SHADOW_ENDS[surfaceLayer(lowCls, lowMesh)] ?? KERB_SHADOW_ENDS.asphalt!;
    ribbon(kerb, line, -into * kerbShadowWidth / 2, kerbShadowWidth, height, ROAD_MARK_LIFT.rail, { step: Infinity, ramp: into > 0 ? { left: KERB_SHADOW_TINT, right: end } : { left: end, right: KERB_SHADOW_TINT } });
    // Posts along the pavement's kerb, not round the planted berms, islands and squares (roads lane R1 doubled the
    // kerbs of -1_-1 with those; the bollards stay at main's count, 25k against 24k triangles).
    const upper = lowLeft ? right : left;
    if (input.canalSide && input.lod === 0 && !(upper && ANCILLARY_CLASSES.includes(upper))) {
      const before = get('bollard').positions.length;
      traceMark(get('bollard'), 'bgtKerb');
      bollards(get('bollard'), line, into * 0.3, height, KERB_TOP, input.canalSide);
      stats.bollards += (get('bollard').positions.length - before) / 27;
    }
  }
  for (const l of Object.keys(layers) as RoadLayer[]) if (!layers[l]!.indices.length) delete layers[l];
  stats.ms = Date.now() - t0;
  return { layers, stats, skipped, ...(carry ? { lowDeck: (k: number) => lowDeckSet.has(k) } : {}) };
}

/** redDedupe: a probe this close to either polygon's ring is on their shared edge, not in an overlap. */
export const RED_OVERLAP_MIN_M = 0.05;
/** bridgeCarry: a kerb this close to a low deck polygon's ring is on the deck's edge and stays. */
export const KERB_ON_DECK_EDGE_M = 0.1;
function ringDistance(rings: readonly (readonly Vec2[])[], x: number, y: number): number {
  let best = Infinity;
  for (const r of rings) for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
    const ax = r[j][0], ay = r[j][1], dx = r[i][0] - ax, dy = r[i][1] - ay, l2 = dx * dx + dy * dy;
    const t = l2 ? Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / l2)) : 0;
    best = Math.min(best, Math.hypot(x - ax - t * dx, y - ay - t * dy));
  }
  return best;
}

/** A kerb run as metres (roadCells decodeRoadLine), simplified to `simplifyM` (densifyOnRelief adds the stations). */
function decodeKerb(e: readonly number[], simplifyM: number = KERB_SIMPLIFY_M): Vec2[] {
  const out: Vec2[] = [];
  let x = 0, y = 0;
  for (let i = 0; i + 1 < e.length; i += 2) { x += e[i]; y += e[i + 1]; out.push([x / 10, y / 10]); }
  return out.length >= 2 ? simplifyLine(out, simplifyM) : out;
}

// ------------------------------------------------------------------ extractor helpers (also the fixture and tests)

/**
 * Shared edges between a low-class and a high-class polygon at equal `h` (roadCells kerbBetween), merged into
 * runs. Vertices match exactly after rounding to `tol` metres (the survey's neighbours share vertices to the
 * centimetre within one bronhouder). Returns polylines in metres.
 */
export function kerbEdges(polys: readonly { c: RoadClass; h: number; rings: readonly (readonly Vec2[])[] }[], tol = 0.01): Vec2[][] {
  const q = (v: number) => Math.round(v / tol);
  const vkey = (p: readonly number[]) => `${q(p[0])},${q(p[1])}`;
  const edges = new Map<string, { a: Vec2; b: Vec2; owners: number[] }>();
  polys.forEach((poly, k) => {
    for (const ring of poly.rings) {
      const pts = ring.length > 1 && ring[0][0] === ring[ring.length - 1][0] && ring[0][1] === ring[ring.length - 1][1] ? ring.slice(0, -1) : ring;
      for (let i = 0; i < pts.length; i++) {
        const a = pts[i], b = pts[(i + 1) % pts.length], ka = vkey(a), kb = vkey(b);
        if (ka === kb) continue;
        const key = ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
        const e = edges.get(key);
        if (e) e.owners.push(k); else edges.set(key, { a: [a[0], a[1]], b: [b[0], b[1]], owners: [k] });
      }
    }
  });
  const low = (c: RoadClass) => (KERB_LOW_CLASSES as readonly RoadClass[]).includes(c);
  const segs: [Vec2, Vec2][] = [];
  for (const e of edges.values()) {
    if (e.owners.length !== 2) continue;
    const p = polys[e.owners[0]], r = polys[e.owners[1]];
    if (p.h !== r.h || low(p.c) === low(r.c)) continue;
    // Both classes must be kerb classes (a parking bay beside a carriageway is low/low, skipped above; a driveway beside a footway high/high).
    segs.push([e.a, e.b]);
  }
  // Chain segments into runs by shared endpoints.
  const byEnd = new Map<string, number[]>();
  segs.forEach((s, i) => { for (const p of s) { const k = vkey(p); (byEnd.get(k) ?? byEnd.set(k, []).get(k)!).push(i); } });
  const used = new Set<number>(), out: Vec2[][] = [];
  const extend = (run: Vec2[], fromEnd: boolean) => {
    for (;;) {
      const tip = fromEnd ? run[run.length - 1] : run[0], k = vkey(tip);
      const next = (byEnd.get(k) ?? []).find(i => !used.has(i));
      if (next === undefined) return;
      used.add(next);
      const [a, b] = segs[next], other = vkey(a) === k ? b : a;
      if (fromEnd) run.push(other); else run.unshift(other);
    }
  };
  segs.forEach((s, i) => {
    if (used.has(i)) return;
    used.add(i);
    const run: Vec2[] = [s[0], s[1]];
    extend(run, true); extend(run, false);
    out.push(run);
  });
  return out;
}

/**
 * Share of a polyline's stations (every `step` metres, the ends included) lying inside a polygon `inside`
 * accepts: the cover test for roadCells coverWays (≥ 0.8 → the way emits no bands).
 */
export function coveredShare(line: readonly Vec2[], inside: (x: number, y: number) => boolean, step = 2): number {
  const st = stations(line), total = st[st.length - 1];
  if (!(total > 0)) return 0;
  let n = 0, hit = 0;
  for (let s = 0; s <= total + 1e-6; s += step) {
    const t = Math.min(s, total);
    let i = 1; while (i < st.length - 1 && st[i] < t) i++;
    const u = (t - st[i - 1]) / ((st[i] - st[i - 1]) || 1), p: Vec2 = [line[i - 1][0] + (line[i][0] - line[i - 1][0]) * u, line[i - 1][1] + (line[i][1] - line[i - 1][1]) * u];
    n++;
    if (inside(p[0], p[1])) hit++;
  }
  return hit / n;
}
export const COVER_SHARE = 0.8;

/** Douglas–Peucker simplification of an open or closed ring to `tol` metres (the extract's 0.1 m). */
export function simplifyRing(pts: readonly Vec2[], tol: number): Vec2[] {
  if (pts.length <= 4) return pts.map(p => [p[0], p[1]]);
  const closed = pts[0][0] === pts[pts.length - 1][0] && pts[0][1] === pts[pts.length - 1][1];
  const open = closed ? pts.slice(0, -1) : pts;
  // A closed ring: split at the farthest vertex from the first so both halves are open chains.
  let far = 1, best = -1;
  for (let i = 1; i < open.length; i++) { const d = (open[i][0] - open[0][0]) ** 2 + (open[i][1] - open[0][1]) ** 2; if (d > best) { best = d; far = i; } }
  const dp = (a: number, b: number, keep: boolean[]) => {
    if (b - a < 2) return;
    const p = open[a], q = open[b], dx = q[0] - p[0], dy = q[1] - p[1], l = Math.hypot(dx, dy);
    let worst = 0, at = -1;
    for (let i = a + 1; i < b; i++) {
      const d = l > 1e-9 ? Math.abs((open[i][0] - p[0]) * dy - (open[i][1] - p[1]) * dx) / l : Math.hypot(open[i][0] - p[0], open[i][1] - p[1]);
      if (d > worst) { worst = d; at = i; }
    }
    if (worst > tol && at > 0) { keep[at] = true; dp(a, at, keep); dp(at, b, keep); }
  };
  const keep = new Array<boolean>(open.length).fill(false);
  keep[0] = true; keep[far] = true; keep[open.length - 1] = true;
  dp(0, far, keep); dp(far, open.length - 1, keep);
  const out = open.filter((_, i) => keep[i]).map(p => [p[0], p[1]] as Vec2);
  // Consecutive duplicates (the survey repeats vertices) go; the closing vertex is not repeated.
  const dedup: Vec2[] = [];
  for (const p of out) if (!dedup.length || Math.hypot(p[0] - dedup[dedup.length - 1][0], p[1] - dedup[dedup.length - 1][1]) > 1e-9) dedup.push(p);
  if (dedup.length > 1 && Math.hypot(dedup[0][0] - dedup[dedup.length - 1][0], dedup[0][1] - dedup[dedup.length - 1][1]) <= 1e-9) dedup.pop();
  return dedup;
}
